fn main(){let args:Vec<String>=env::args().collect();assert_eq!(args.len(),6);let spaces=read(&args[1]);let v=&spaces[2];let base=&spaces[0];let zero=&spaces[1];let r=read_class37(&args[4]);let order=fs::read_to_string(&args[3]).unwrap();let mut d=vec![];for line in order.lines(){let p:Vec<_>=line.split_whitespace().collect();assert_eq!(p.len(),4);assert_eq!(p[0].parse::<usize>().unwrap(),d.len());d.push(read_basis36(&format!("{}/coupled-{}-basis.txt",args[2],p[1])));}assert_eq!(d.len(),10);let mut table=[[0u8;32];32];for a in 0..32{for b in 0..32{table[a][b]=field(a as u8,b as u8);assert_eq!(table[a][b],field_independent(a as u8,b as u8));}}
 fs::create_dir(&args[5]).unwrap();let mut out=BufWriter::new(fs::File::create(format!("{}/diamond-certificates.txt",args[5])).unwrap());
 let d12=add37("shifted-positive-double2",v,base,&d[1],&d[1],&table,&mut out);let mut pos=add37("shifted-positive-double4",v,base,&d12,&d12,&table,&mut out);for k in [2usize,4,8,0]{pos=add37(&format!("shifted-positive-{k}"),v,base,&pos,&d[k],&table,&mut out);}
 let d62=add37("shifted-negative-double2",v,base,&d[6],&d[6],&table,&mut out);let mut neg=add37("shifted-negative-double4",v,base,&d62,&d62,&table,&mut out);for k in [3usize,5,7,9]{neg=add37(&format!("shifted-negative-{k}"),v,base,&neg,&d[k],&table,&mut out);}
 let minus=negate37("shifted-minus-negative",v,base,&neg,&table,&mut out);let te=add37("shifted-E",v,base,&pos,&minus,&table,&mut out);let tr=multiply37("shifted-cofactor61",v,base,&te,61,&table,&mut out);save37(&args[5],"T-E",&te);save37(&args[5],"T-R",&tr);
 let mut scalar=zero.clone();let mut hits=vec![];for k in 0..11{let equal=same37(&format!("diamond-scalar-{k}"),v,&tr,&scalar,&table,&mut out);if equal{hits.push(k);}println!("DIAMOND39_SCALAR scalar={k} equivalent={equal}");if k==6{save37(&args[5],"six-R",&scalar);}if k==0{scalar=r.clone();}else{scalar=add37(&format!("scalar-next-{}",k+1),v,base,&scalar,&r,&table,&mut out);}}
 assert!(hits.len()<=1);assert!(same37("source-eleven-cycle",v,&scalar,zero,&table,&mut out));let tr11=multiply37("image-eleven",v,base,&tr,11,&table,&mut out);assert!(same37("image-eleven-zero",v,&tr11,zero,&table,&mut out));assert!(!same37("image-nonzero",v,&tr,zero,&table,&mut out));let character=hits.first().copied().unwrap_or(-1);assert_ne!(character,0);out.flush().unwrap();fs::write(format!("{}/diamond-result.txt",args[5]),format!("scalar_character={character}\nexpected_six_matches={}\nimage_nonzero=true\nimage_eleven_zero=true\n",character==6)).unwrap();println!("DIAMOND39_RESULT full_deck_shift=true image_nonzero=true image_eleven_zero=true scalar_character={character} expected_six_matches={} scalar_tests=11 all_generator_memberships=checked independent_products=all intended_sign_factor_evaluated=false",character==6);println!("DIAMOND39_ALL_CHECKS_PASS");}
